import{_ as a}from"./chunks/thumb-10.CtKDnHZc.js";import{_ as o}from"./chunks/photo-16.CbRZxUng.js";import{_ as r,H as e,f as i,i as s}from"./chunks/framework.Cvt1eIE0.js";const f=JSON.parse('{"title":"短剧与三分钟热搜：注意力政治时代的阅读症候","description":"","frontmatter":{"title":"短剧与三分钟热搜：注意力政治时代的阅读症候","date":"2026-02-14T00:00:00.000Z","category":"阅读","tags":["阅读","评论","媒介"],"excerpt":"当新闻也按爽点剪辑，我们是在知情，还是在消费情绪？这对长文阅读与公共讨论意味着什么。"},"headers":[],"relativePath":"posts/阅读/short-video-attention-politics.md","filePath":"posts/阅读/short-video-attention-politics.md"}'),n={name:"posts/阅读/short-video-attention-politics.md"};function l(d,t,c,p,h,_){return e(),i("div",null,[...t[0]||(t[0]=[s('<img src="'+a+'" alt="配图" class="article-banner" loading="lazy"><div class="figure wide"><img src="'+o+'" alt="随拍配图" loading="lazy"><p class="figure-caption">屏幕越亮，越需要为自己留一段慢下来的时间。</p></div><h1 id="短剧与三分钟热搜" tabindex="-1">短剧与三分钟热搜 <a class="header-anchor" href="#短剧与三分钟热搜" aria-label="Permalink to &quot;短剧与三分钟热搜&quot;">​</a></h1><p>2026 年的内容平台有个共同趋势：<strong>把复杂事件压缩成可滑走的情绪包</strong>。短剧负责虚构爽感，热搜负责现实爽感；二者共享同一套机制——高潮前置、对立人设、反转收尾。</p><h2 id="这如何改变「阅读」" tabindex="-1">这如何改变「阅读」 <a class="header-anchor" href="#这如何改变「阅读」" aria-label="Permalink to &quot;这如何改变「阅读」&quot;">​</a></h2><p><strong>事实让位于姿态</strong>：你知道谁站在哪边，却不知道事件时间线。<br><strong>共情被定向</strong>：镜头只给受害者或只给施暴者，取决于叙事需要。<br><strong>讨论变成表演</strong>：评论不是为了说服，而是为了被看见站队。</p><h2 id="与「慢阅读」的对抗关系" tabindex="-1">与「慢阅读」的对抗关系 <a class="header-anchor" href="#与「慢阅读」的对抗关系" aria-label="Permalink to &quot;与「慢阅读」的对抗关系&quot;">​</a></h2><p>我仍相信纸书、长文、手写批注的价值，不是因为怀旧，而是因为<strong>公共理性需要更长的时间常数</strong>。一条热搜的生命周期可能只有 36 小时；一个政策的后果可能是 36 个月。</p><h2 id="可操作的自我保护" tabindex="-1">可操作的自我保护 <a class="header-anchor" href="#可操作的自我保护" aria-label="Permalink to &quot;可操作的自我保护&quot;">​</a></h2><ul><li>看到热搜先查<strong>三家以上</strong>不同来源的时间线。</li><li>把情绪强烈的帖子标记为「待核实」，延迟转发。</li><li>每周固定一段无推送阅读（纸书或长 PDF 均可）。</li></ul><h2 id="收束" tabindex="-1">收束 <a class="header-anchor" href="#收束" aria-label="Permalink to &quot;收束&quot;">​</a></h2><p>注意力政治不只会偷走时间，还会<strong>重塑你认为重要的议题</strong>。在收藏夹里多留几篇慢文，不等于逃避世界，而是给判断留一点缓冲区。</p><hr><p><em>媒介环境持续变化，欢迎用更新事实修正本文。</em></p>',14)])])}const b=r(n,[["render",l]]);export{f as __pageData,b as default};
